/** A registered prefix, for example `'prj'`. */
export type Prefix = (typeof PREFIXES)[number]['prefix']

const REGISTERED: ReadonlySet<string> = new Set(PREFIXES.map((p) => p.prefix))
/** Lowercase Crockford base32 (no `i`, `l`, `o`, `u`). */
const ALPHABET = '0123456789abcdefghjkmnpqrstvwxyz'
const SUFFIX_LEN = 26
const PREFIX_SHAPE = /^[a-z]{2,5}$/
const HEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/

